import { CALCULUS_MODELLING_CONTEXTS, MODELLING_STAGE_IDS, buildModellingScaffold, compareExactAndNumerical } from './calculus-modelling-scaffold.js';
function el(d,t,c,x=''){const n=d.createElement(t);if(c)n.className=c;if(x)n.textContent=x;return n;}
const ids=new Set(['framework','contexts','method-choice','exact-vs-numerical','interpret-limitations','combined-tools'].map(s=>`activity:y13:modelling:calculus:understand:${s}`));
export class CalculusModellingUnderstandExperience{
 constructor(host,{documentRef=host?.ownerDocument??globalThis.document}={}){this.host=host;this.document=documentRef;}
 supports(id){return ids.has(id);} destroy(){this.host.replaceChildren();this.host.classList.remove('calculus-modelling-understand');}
 render(id){if(!this.supports(id))return false;this.destroy();this.host.classList.add('calculus-modelling-understand');this.renderSlug(id.split(':').at(-1));return true;}
 panel(title,eyebrow,body){const p=el(this.document,'section','calculus-modelling__panel');const h=el(this.document,'header','calculus-modelling__header');h.append(el(this.document,'span','calculus-modelling__eyebrow',eyebrow),el(this.document,'h3','',title),el(this.document,'p','',body));p.append(h);this.host.append(p);return p;}
 scaffold(panel,context,{revealMethod=true}={}){const grid=el(this.document,'ol','calculus-modelling__scaffold');for(const stage of buildModellingScaffold(context,{revealMethod})){const li=el(this.document,'li','calculus-modelling__stage');li.dataset.stage=stage.id;li.append(el(this.document,'span','calculus-modelling__number',String(stage.index)),el(this.document,'strong','',stage.label),el(this.document,'p','',stage.summary));if(stage.hidden)li.classList.add('is-hidden-method');grid.append(li);}panel.append(grid);}
 renderSlug(slug){
  if(slug==='framework'){const c=CALCULUS_MODELLING_CONTEXTS[0],p=this.panel('One scaffold for every modelling question','Plan 38.2 · Consistent framework','The context changes; the modelling sequence does not. Complete the model and target before choosing calculus.');this.scaffold(p,c);return;}
  if(slug==='contexts'){const p=this.panel('Same seven stages across the course','Plan 38.1 · Full-skill modelling','Every card uses the same scaffold. Only the relationship, target and calculus route change.');const g=el(this.document,'div','calculus-modelling__contexts');for(const c of CALCULUS_MODELLING_CONTEXTS){const a=el(this.document,'article','calculus-modelling__context');a.append(el(this.document,'strong','',c.label),el(this.document,'p','',c.prompt),el(this.document,'small','',`Support: ${c.support.topicId.replace('topic:y13:','').replaceAll(':',' › ')}`));g.append(a);}p.append(g);return;}
  if(slug==='method-choice'){const c=CALCULUS_MODELLING_CONTEXTS[1],p=this.panel('Do not reveal the technique too early','Plan 38 · AO3 discipline','Read the situation, define variables, build the relationship and identify the target before committing to a calculus method.');this.scaffold(p,c,{revealMethod:false});const b=el(this.document,'button','calculus-modelling__reveal','Reveal method stage');b.type='button';b.addEventListener('click',()=>{b.remove();this.scaffold(p,c,{revealMethod:true});});p.append(b);return;}
  if(slug==='exact-vs-numerical'){const p=this.panel('Exact, trapezium rule, or numerical check?','Plan 38.3 · Method choice','Choose from the information available, not from habit. A calculator may check a model after setup, but should not replace the setup.');const cases=[['Formula + practical antiderivative',compareExactAndNumerical({hasFormula:true,exactAntiderivativePractical:true})],['Only sampled table',compareExactAndNumerical({hasOnlyTable:true})],['Formula but awkward exact evaluation',compareExactAndNumerical({hasFormula:true,exactAntiderivativePractical:false})]];const g=el(this.document,'div','calculus-modelling__contexts');for(const [name,r] of cases){const a=el(this.document,'article','calculus-modelling__context');a.append(el(this.document,'strong','',name),el(this.document,'p','',`${r.choice}: ${r.reason}`));g.append(a);}p.append(g);return;}
  if(slug==='interpret-limitations'){const p=this.panel('A calculated number is not the end','Plan 38.2 · Interpret','Every model answer should be read back into the context.');const list=el(this.document,'ul','calculus-modelling__checks');for(const x of ['sign — increase/decrease or direction','size — plausible magnitude','units — derived from the target quantity','domain/restrictions — where the mathematics is valid','assumptions — what the model treats as constant/ideal','limitations — where extrapolation may fail'])list.append(el(this.document,'li','',x));p.append(list);return;}
  if(slug==='combined-tools'){const p=this.panel('Several tools, one layout','Plan 38.1 · Combined modelling','A representative problem may need more than one earlier calculus tool. The scaffold does not change.');for(const c of [CALCULUS_MODELLING_CONTEXTS[1],CALCULUS_MODELLING_CONTEXTS[4],CALCULUS_MODELLING_CONTEXTS[6]]){const a=el(this.document,'article','calculus-modelling__worked');a.append(el(this.document,'strong','',c.label),el(this.document,'p','',c.prompt),el(this.document,'p','',`Possible tool chain: ${c.techniqueTags.join(' → ')}`));p.append(a);}return;}
 }
}
export function createCalculusModellingUnderstandExperience(host,opts){return new CalculusModellingUnderstandExperience(host,opts);}
